import React, { useEffect } from "react";

export default function UserDashboard() {
  useEffect(() => {
    const token = localStorage.getItem("accessToken");
    if (!token) {
      window.location.href = "/login";
    }
  }, []);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-orange-100 via-orange-200 to-orange-300 dark:from-orange-950 dark:via-orange-900 dark:to-orange-800">
      <div className="bg-white dark:bg-background rounded-2xl shadow-2xl p-8 w-full max-w-lg border border-border text-center">
        <h1 className="text-3xl font-bold mb-4 text-orange-700 dark:text-orange-400" style={{ fontFamily: 'Playfair Display, Georgia, serif' }}>User Dashboard</h1>
        <p className="text-lg text-muted-foreground mb-2" style={{ fontFamily: 'Crimson Text, Georgia, serif' }}>Welcome, user!</p>
        <div className="mt-6">
          {/* Add more dashboard content here */}
        </div>
      </div>
    </div>
  );
}
